from taf.collectors.l2stream3.collector import SbtsL2StreamCollector, \
    VduL2StreamCollector, CoamCUL2StreamCollector
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.core.factories.collector_factory import CoamSbtsCollectorFactory, \
    VduCollectorFactory, CoamCUCollectorFactory
from taf.internal.execution.base import CreatingExecutor
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class L2StreamCollectorFactoryBase(CreatingExecutor('local_executor', None), NamedComponentFactory): # type: ignore[misc]
    _optional_parameters = {"destination_ip_addr",
                            "l2_stream_configuration",
                            "destination_port_number",
                            "dscp"}


class SbtsL2StreamCollectorFactory(CoamSbtsCollectorFactory,
                                   L2StreamCollectorFactoryBase):
    """
       factory to create SBTS admin cli l2stream collectors
    """
    _optional_parameters = {"source_ip_addr", "start_timeout", "stop_timeout", "tti_dec_path"}
    _product_class = SbtsL2StreamCollector


class VduL2StreamCollectorFactory(VduCollectorFactory,
                                  L2StreamCollectorFactoryBase):
    """
       factory to create Vdu l2stream collectors
    """

    _optional_parameters = {"timeout", "tti_dec_path"}
    _product_class = VduL2StreamCollector


class CoamCUL2StreamCollectorFactory(CoamCUCollectorFactory,
                                     L2StreamCollectorFactoryBase):
    """
       factory to create Vdu l2stream collectors
    """

    _optional_parameters = {"timeout"}
    _product_class = CoamCUL2StreamCollector
